function buildingMarkup(){return list('locaties').filter(r=>r.footprint).map(r=>{const f=r.footprint,x=f.col*32,y=f.row*32,w=f.w*32,h=f.h*32,n=Array.from(r.id).reduce((a,c)=>a+c.charCodeAt(0),0),style=r.appearance&&r.appearance!=='auto'?r.appearance:['tile','thatch','slate','timber'][n%4],colors={tile:['#b56f50','#864735'],thatch:['#c9ad69','#968047'],slate:['#7d8791','#505b67'],timber:['#a58a6e','#705a45']},[light,dark]=colors[style]||colors.tile;const horizontal=w>=h;let lines='';for(let i=8;i<(horizontal?w:h)-4;i+=7)lines+=horizontal?`<path d="M${x+i} ${y+4}v${h-8}"/>`:`<path d="M${x+4} ${y+i}h${w-8}"/>`;const clipId='roof-'+r.id.replace(/[^a-zA-Z0-9_-]/g,'');const clip=footprintCells(f).map(([cx,cy])=>`<rect x="${(cx+f.col)*32}" y="${(cy+f.row)*32}" width="32" height="32"/>`).join('');return `<g class="building pin" data-id="${esc(r.id)}" tabindex="0" role="button" aria-label="${esc(r.name)}"><title>${esc(r.name)}</title><defs><clipPath id="${clipId}">${clip}</clipPath></defs><g clip-path="url(#${clipId})"><rect x="${x+4}" y="${y+6}" width="${w-6}" height="${h-6}" rx="3" fill="#28372e" opacity=".22"/><rect x="${x+2}" y="${y+2}" width="${w-6}" height="${h-6}" rx="2" fill="${light}" stroke="${selected===r.id?'#e0b85d':'#594b3e'}" stroke-width="2"/><path d="${horizontal?`M${x+3} ${y+h/2}H${x+w-4}V${y+h-4}H${x+3}Z`:`M${x+w/2} ${y+3}V${y+h-4}H${x+w-4}V${y+3}Z`}" fill="${dark}"/><g stroke="#e8d9b4" opacity=".3" stroke-width="1">${lines}</g><path d="${horizontal?`M${x+3} ${y+h/2}H${x+w-4}`:`M${x+w/2} ${y+3}V${y+h-4}`}" stroke="#493d32" stroke-width="2"/><rect x="${x+w*.68}" y="${y+h*.22}" width="6" height="9" fill="#61574f" stroke="#d4c5ac" stroke-width="1"/></g><path d="${outlinePath(f)}" fill="none" stroke="${selected===r.id?'#e0b85d':'#594b3e'}" stroke-width="2" pointer-events="none"/><text class="building-label" x="${x+w/2}" y="${y+h+12}" text-anchor="middle" fill="#283c30" stroke="#faf4e7" stroke-width="3" paint-order="stroke" font-size="11">${esc(r.name)}</text></g>`}).join('')}
function svg(){if(!data.map)return demoSvg();const w=mapWidth(),h=mapHeight();return `<svg id="map" viewBox="0 0 ${w} ${h}" aria-label="Eigen kaart van ${esc(data.villageName)}" tabindex="0"><defs><pattern id="waterTexture" width="110" height="70" patternUnits="userSpaceOnUse"><rect width="110" height="70" fill="#91bdc4"/><path d="M12 22q12-4 24 0m32 25q12-4 24 0" stroke="#c3dcdf" opacity=".5" fill="none"/></pattern><pattern id="customGrid" width="32" height="32" patternUnits="userSpaceOnUse"><path d="M32 0H0V32" fill="none" stroke="#3b5240" stroke-opacity=".3" stroke-width="1"/></pattern></defs><rect width="${w}" height="${h}" fill="#eee8d8"/>${referenceMarkup()}<g id="terrainCells" opacity="${data.map.reference&&data.map.reference.visible!==false?.45:1}">${terrainMarkup()}</g><g id="freeLayers">${freeMarkup()}</g><g id="plots">${plotsMarkup()}</g><g id="nature">${natureMarkup()}</g><g id="bridges">${terrainMarkup(true)}</g><rect id="gridOverlay" width="${w}" height="${h}" fill="url(#customGrid)" pointer-events="none" ${data.map.grid?'':'visibility="hidden"'}/><g id="buildings">${buildingMarkup()}</g>${drawing?'':list('locaties').filter(r=>!r.footprint).map(r=>`<g class="pin" data-id="${esc(r.id)}" transform="translate(${r.x*w/100},${r.y*h/100})" tabindex="0" role="button" aria-label="${esc(r.name)}"><circle r="16" fill="${selected===r.id?'#b08949':'#294638'}" stroke="#faf4df" stroke-width="3"/><text text-anchor="middle" y="5" fill="white" font-size="18">⌂</text><text text-anchor="middle" y="33" fill="#334738" font-size="12">${esc(r.name)}</text></g>`).join('')}<g id="draftLayer">${draftMarkup()}</g><rect id="brushPreview" fill="#f9df8e55" stroke="#a47b3f" stroke-width="2" pointer-events="none" visibility="hidden"/></svg>`}
function terrainMarkup(bridgeOnly=false){let out='';const cells=data.map.cells;for(let y=0;y<data.map.rows;y++){let x=0;while(x<data.map.cols){const type=cells[x+','+y];if(!type||(bridgeOnly?type!=='bridge':type==='bridge')){x++;continue}let end=x+1;if(['grass','water','road'].includes(type))while(end<data.map.cols&&cells[end+','+y]===type)end++;const px=x*32,py=y*32,w=(end-x)*32;let shape=`<rect x="${px}" y="${py}" width="${w}" height="32" shape-rendering="crispEdges" fill="${type==='grass'?'#aac390':type==='water'?'url(#waterTexture)':type==='road'?'#d1ba94':type==='trees'?'#aac390':'url(#waterTexture)'}"/>`;if(type==='trees'){const n=(x*17+y*13)%9;shape+=treeAsset(px+15+(n%3),py+16,n,14)}if(type==='bridge'){const vertical=data.map.vertical?.includes(x+','+y);shape+=`<g transform="translate(${px} ${py}) ${vertical?'rotate(90 16 16)':''}"><rect y="4" width="32" height="24" fill="#ae8555"/><path d="M0 4h32M0 28h32" stroke="#705538" stroke-width="3"/><path d="M5 6v20M12 6v20M19 6v20M26 6v20" stroke="#d9b888"/></g>`}out+=shape;x=end}}return out}
function beginMap(){remember();data.map={cells:{},vertical:[],grid:true,cols:40,rows:27};drawing=true;place=null;persist();render();toast('Stel het aantal kolommen en rijen in en begin met tekenen.')}
