function exportRecords(collection,format){const rows=collection==='percelen'?(data.map?.plots||[]):data[collection];const label=collection==='facties'?'gildes':collection,base=(data.villageName||'plaats').toLowerCase().replace(/[^a-z0-9]+/g,'-')+'-'+label;if(format==='json'){downloadData(JSON.stringify({app:'Fantasy Village Mapper',version:'1.35.0',placeName:data.villageName,collection:label,records:rows},null,2),base+'.json');return}const fields=collection==='percelen'?['id','name','ownerId','eigenaar','cells']:collection==='inwoners'?['id','name','kind','description','secret','location','woning','workplace','werkplaats','portrait']:['id','name','kind','description','secret','hidden','ownerId','eigenaar','footprint'];const prepared=rows.map(r=>({...r,eigenaar:data.inwoners.find(n=>n.id===r.ownerId)?.name||'',woning:data.locaties.find(l=>l.id===r.location)?.name||'',werkplaats:data.locaties.find(l=>l.id===r.workplace)?.name||'',cells:collection==='percelen'?plotCells(r):r.cells}));const quote=v=>{let s=typeof v==='object'&&v!==null?JSON.stringify(v):String(v??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'};downloadData('\uFEFF'+[fields.map(quote).join(','),...prepared.map(r=>fields.map(k=>quote(r[k])).join(','))].join('\r\n'),base+'.csv','text/csv;charset=utf-8')}
