let terrainChoice='grass',terrainAction='draw';let plotEditMode='add';let buildingDraft=[],plotDraft=[];
function packCells(cells){const unique=[...new Map(cells.map(c=>[c.join(','),c])).values()],minX=Math.min(...unique.map(c=>c[0])),minY=Math.min(...unique.map(c=>c[1]));return {col:minX,row:minY,w:Math.max(...unique.map(c=>c[0]))-minX+1,h:Math.max(...unique.map(c=>c[1]))-minY+1,cells:unique.map(([x,y])=>[x-minX,y-minY])}}
function connectedPlotCells(cells){const left=new Set(cells.map(c=>c.join(','))),groups=[];while(left.size){const key=left.values().next().value;left.delete(key);const queue=[key.split(',').map(Number)];for(let i=0;i<queue.length;i++){const [x,y]=queue[i];for(const c of [[x-1,y],[x+1,y],[x,y-1],[x,y+1]]){const k=c.join(',');if(left.delete(k))queue.push(c)}}groups.push(queue)}return groups}
function mergeOwnerPlots(ownerId){if(!data.map)return;let changed=false;for(const p of [...data.map.plots]){if((p.ownerId||'')!==(ownerId||''))continue;const groups=connectedPlotCells(plotCells(p));if(groups.length>1){assignPlotCells(p,groups[0]);for(const cells of groups.slice(1)){const q={...structuredClone(p),id:crypto.randomUUID(),name:(p.name||data.inwoners.find(n=>n.id===p.ownerId)?.name||'Perceel')+' — deel '+(groups.indexOf(cells)+1)};assignPlotCells(q,cells);data.map.plots.push(q)}changed=true}}let merged=true;while(merged){merged=false;const owned=data.map.plots.filter(p=>ownerId&&p.ownerId===ownerId);outer:for(let i=0;i<owned.length;i++)for(let j=i+1;j<owned.length;j++){const a=owned[i],b=owned[j],cells=[...plotCells(a),...plotCells(b)];if(connectedPlotCells(cells).length!==1)continue;a.mergedNames=[...new Set([a.name,b.name,...(a.mergedNames||[]),...(b.mergedNames||[])].filter(Boolean))];assignPlotCells(a,cells);if(!a.name)a.name=b.name||'';if(data.finance?.plotRules){const ar=data.finance.plotRules[a.id]||{},br=data.finance.plotRules[b.id]||{};data.finance.plotRules[a.id]=Object.fromEntries(['income','upkeep','cost'].map(k=>[k,Number(ar[k]||0)+Number(br[k]||0)]));delete data.finance.plotRules[b.id]}data.map.plots=data.map.plots.filter(p=>p.id!==b.id);if(plotExpandId===b.id)plotExpandId=a.id;changed=merged=true;break outer}}if(changed)persist()}

function draftMarkup(){let result='';for(const [cells,color]of [[buildingDraft,'#b47e64'],[plotDraft,'#d7b960']])for(const [x,y]of cells)result+=`<rect x="${x*32}" y="${y*32}" width="32" height="32" fill="${color}" opacity=".65" stroke="#f8e8bb" stroke-width="1"/>`;return result}
function hideDrawingOptions(){toolSection=null;const panel=$('.map-editor');panel?.classList.remove('options-open');const dock=$('.tool-popover');if(dock)dock.hidden=true;refreshActiveTool(panel)}
function cellsConnected(cells){const keys=new Set(cells.map(c=>c.join(','))),seen=new Set(),queue=[cells[0]];while(queue.length){const [x,y]=queue.pop(),k=x+','+y;if(seen.has(k)||!keys.has(k))continue;seen.add(k);queue.push([x+1,y],[x-1,y],[x,y+1],[x,y-1])}return seen.size===keys.size}
function bindDirectPaint(kind){const map=$('#map');map.classList.add('painting');map.onclick=null;let pointer=null,previous=null,strokeCells=[];function record(c){if(kind==='building'&&data.locaties.some(r=>r.id!==expandBuildingId&&r.footprint&&footprintsOverlap(r.footprint,{col:c[0],row:c[1],w:1,h:1})))return;strokeCells.push(c);if(kind==='building'&&!expandBuildingId)buildingDraft.push(c);if(kind==='plot'&&!plotExpandId&&plotEditMode!=='remove')plotDraft.push(c);$('#draftLayer').innerHTML=draftMarkup()+((kind==='building'&&expandBuildingId||kind==='plot'&&plotExpandId)?strokeCells.map(([x,y])=>`<rect x="${x*32}" y="${y*32}" width="32" height="32" fill="#d7b960" opacity=".6"/>`).join(''):'')}function paint(e){const c=mapCell(e,map);if(previous){let [x,y]=previous;while(x!==c[0]||y!==c[1]){if(x!==c[0])x+=Math.sign(c[0]-x);else y+=Math.sign(c[1]-y);record([x,y])}}else record(c);previous=c;refreshDraftActions()}
map.onpointerdown=e=>{if(e.button!==0)return;e.preventDefault();if(kind==='plot'&&plotEditMode==='remove'&&!plotExpandId){toast('Kies eerst het perceel dat je wilt verkleinen.');return}hideDrawingOptions();pointer=e.pointerId;previous=null;strokeCells=[];map.setPointerCapture(pointer);paint(e)};map.onpointermove=e=>{if(pointer===e.pointerId)paint(e)};map.onpointerup=e=>{if(pointer!==e.pointerId)return;paint(e);pointer=null;previous=null;if(!strokeCells.length)return;if(kind==='building'&&expandBuildingId){const r=data.locaties.find(r=>r.id===expandBuildingId),f=packCells(strokeCells);if(!r||!footprintTouches(r.footprint,f)){toast('Teken tegen het bestaande pand aan.');return}remember();r.footprint=mergeFootprints(r.footprint,f);r.x=(r.footprint.col+r.footprint.w/2)/data.map.cols*100;r.y=(r.footprint.row+r.footprint.h/2)/data.map.rows*100;persist();render()}else if(kind==='plot'&&plotExpandId){const p=data.map.plots.find(p=>p.id===plotExpandId);if(!p)return;remember();if(plotEditMode==='remove'){const removed=new Set(strokeCells.map(c=>c.join(','))),remaining=plotCells(p).filter(c=>!removed.has(c.join(',')));if(remaining.length)assignPlotCells(p,remaining);else{data.map.plots=data.map.plots.filter(q=>q.id!==p.id);plotExpandId='';}persist();render();toast(remaining.length?'Perceel verkleind.':'Laatste vak verwijderd. Gebruik Ongedaan om het te herstellen.')}else{assignPlotCells(p,[...plotCells(p),...strokeCells]);mergeOwnerPlots(p.ownerId);persist();render()}}};map.onpointercancel=()=>{pointer=null;previous=null}}
function refreshDraftActions(){const bar=$('.map-top');if(!bar)return;let actions=$('#draftActions');if(!buildingDraft.length&&!plotDraft.length){actions?.remove();return}if(!actions){actions=document.createElement('div');actions.id='draftActions';$('.map-editor').append(actions)}actions.innerHTML=`<button id="finishDraft">${buildingDraft.length?'Pand':'Perceel'} bewaren</button><button id="cancelDraft">Tekening annuleren</button>`;$('#finishDraft').onclick=()=>{if(buildingDraft.length){const unique=[...new Map(buildingDraft.map(c=>[c.join(','),c])).values()];if(!cellsConnected(unique)){toast('Verbind alle delen van het pand met aansluitende vakken.');return}pendingBuilding=packCells(unique);edit('locaties');$('#form').elements.kind.value=brush==='workshop'?'smallWorkshop':'tent';$('#form').elements.kind.dispatchEvent(new Event('change',{bubbles:true}));$('#placement').hidden=true}else{const f=packCells(plotDraft);editPlot(null,{x:f.col*32,y:f.row*32,w:f.w*32,h:f.h*32,cells:plotDraft.map(c=>[...c])})}};$('#cancelDraft').onclick=()=>{buildingDraft=[];plotDraft=[];render()}}
function playerSvg(){const previous=player,previousDrawing=drawing,draftB=buildingDraft,draftP=plotDraft;try{player=true;drawing=false;buildingDraft=[];plotDraft=[];const str=svg();const doc=new DOMParser().parseFromString(str,'image/svg+xml');doc.querySelector('#referenceImage')?.remove();doc.querySelector('#terrainCells')?.setAttribute('opacity','1');doc.querySelector('#plots')?.remove();doc.querySelector('#draftLayer')?.remove();doc.querySelector('#brushPreview')?.remove();doc.querySelectorAll('title').forEach(t=>t.remove());const out=doc.documentElement;out.setAttribute('xmlns','http://www.w3.org/2000/svg');out.setAttribute('width',mapWidth());out.setAttribute('height',mapHeight());return new XMLSerializer().serializeToString(out)}finally{player=previous;drawing=previousDrawing;buildingDraft=draftB;plotDraft=draftP}}
